package cn.local.psqirecord;

import org.json.*;import java.util.*;

public final class Reports {
 public static final String METHOD="仅纳入已完成且不在回收站的记录；同一病人、日期、量表、规则版本有多份时，取最近保存的一份。统计单位为评估记录，重复随访不是独立患者。各量表分开统计。";
 public static final class Filter {public final String patient,from,to;public Filter(String p,String f,String t){patient=p;from=f==null?"":f;to=t==null?"":t;if(!from.isEmpty())Store.checkDay(from);if(!to.isEmpty())Store.checkDay(to);if(!from.isEmpty()&&!to.isEmpty()&&from.compareTo(to)>0)throw new IllegalArgumentException("开始日期不能晚于结束日期");}boolean accepts(JSONObject r)throws Exception{return (patient==null||patient.equals(r.getString("patientId")))&&(from.isEmpty()||r.getString("day").compareTo(from)>=0)&&(to.isEmpty()||r.getString("day").compareTo(to)<=0);}}
 public static final class Stat {public String scale,rule;public int n,patients;public Double mean,sd,median,min,max;}
 public static List<JSONObject> selected(JSONObject snapshot,Filter f,boolean completedOnly)throws Exception{Set<String>trashed=new HashSet<>();JSONArray ps=snapshot.getJSONArray("patients");for(int i=0;i<ps.length();i++)if(ps.getJSONObject(i).optBoolean("deleted",false))trashed.add(ps.getJSONObject(i).getString("id"));List<JSONObject>out=new ArrayList<>();JSONArray rows=snapshot.getJSONArray("records");for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);if(!trashed.contains(r.getString("patientId"))&&f.accepts(r)&&(!completedOnly||(!r.getBoolean("deleted")&&r.getJSONObject("data").getBoolean("completed"))))out.add(r);}out.sort((a,b)->{int c=b.optString("day").compareTo(a.optString("day"));return c!=0?c:Long.compare(b.optLong("updated"),a.optLong("updated"));});return out;}
 public static List<JSONObject> analytic(JSONObject snapshot,Filter f)throws Exception{Map<String,JSONObject>latest=new LinkedHashMap<>();for(JSONObject r:selected(snapshot,f,true)){JSONObject d=r.getJSONObject("data");String key=r.getString("patientId")+"|"+r.getString("day")+"|"+Store.scaleOf(d.toString())+"|"+d.getString("rule");JSONObject prev=latest.get(key);if(prev==null||r.getLong("updated")>prev.getLong("updated")||(r.getLong("updated")==prev.getLong("updated")&&r.getString("id").compareTo(prev.getString("id"))>0))latest.put(key,r);}return new ArrayList<>(latest.values());}
 public static List<Stat> stats(JSONObject snapshot,Filter f)throws Exception{Map<String,List<JSONObject>>groups=new LinkedHashMap<>();for(String id:Scales.IDS)groups.put(id+"|"+Scales.get(id).rule,new ArrayList<>());for(JSONObject r:analytic(snapshot,f)){JSONObject d=r.getJSONObject("data");String key=Store.scaleOf(d.toString())+"|"+d.getString("rule");if(!groups.containsKey(key))groups.put(key,new ArrayList<>());groups.get(key).add(r);}List<Stat>out=new ArrayList<>();for(Map.Entry<String,List<JSONObject>>entry:groups.entrySet()){String[]key=entry.getKey().split("\\|",2);Stat s=new Stat();s.scale=key[0];s.rule=key[1];s.n=entry.getValue().size();Set<String>people=new HashSet<>();List<Double>values=new ArrayList<>();double sum=0;for(JSONObject r:entry.getValue()){people.add(r.getString("patientId"));double value=r.getJSONObject("data").getDouble("total");values.add(value);sum+=value;}s.patients=people.size();if(s.n>0){Collections.sort(values);s.mean=sum/s.n;s.min=values.get(0);s.max=values.get(s.n-1);s.median=s.n%2==1?values.get(s.n/2):(values.get(s.n/2-1)+values.get(s.n/2))/2;double squared=0;for(double v:values)squared+=(v-s.mean)*(v-s.mean);if(s.n>1)s.sd=Math.sqrt(squared/(s.n-1));}out.add(s);}return out;}
 public static List<Xlsx.Sheet> workbook(JSONObject snap,Filter f)throws Exception{
  Map<String,JSONObject>patients=new LinkedHashMap<>();JSONArray ps=snap.getJSONArray("patients");for(int n=0;n<ps.length();n++){JSONObject p=ps.getJSONObject(n);patients.put(p.getString("id"),p);}
  List<Xlsx.Sheet>sheets=new ArrayList<>();Xlsx.Sheet guide=new Xlsx.Sheet("导出说明");guide.add("项目","内容");guide.add("软件","睡眠随记 0.0.1 · 五量表个人离线采集");guide.add("导出日期",Store.day(snap.getLong("exportedAt")));guide.add("病人范围",f.patient==null?"全部病人":patients.get(f.patient).optString("code"));guide.add("开始日期",f.from.isEmpty()?"不限":f.from);guide.add("结束日期",f.to.isEmpty()?"不限":f.to);guide.add("统计口径",METHOD);guide.add("空白分数","未填写或草稿不计为0。每日汇总仅显示已完成分数，状态单列。");guide.add("重复记录","每日汇总与统计选择最新完成记录；所有副本均保留在逐次评分和条目明细中。");guide.add("规则","PSQI保留用户确认边界；HAMD-17第16题用患者叙述法16a，未评定不算3分。");guide.add("回顾时间","按填写日期保存，不等于量表只回顾一天。PSQI/AIS过去1月，HAMD/HAMA过去1周，NRS当前。");guide.add("使用范围","中文录入提示不等于经独立验证的电子中文版；源表和出处见量表来源。统计为描述性汇总，不作诊断或疗效推断。");guide.add("病人回收站","整位病人移入回收站后不纳入本表；完整备份保留回收站全部内容。");guide.add("备份","Excel用于查看分析；完整恢复使用.psqibak文件。");sheets.add(guide);
  Xlsx.Sheet people=new Xlsx.Sheet("病人档案");people.add("档案ID","病人编号","姓名或称呼","创建日期");for(JSONObject p:patients.values())if(!p.optBoolean("deleted",false)&&(f.patient==null||f.patient.equals(p.getString("id"))))people.add(p.getString("id"),p.getString("code"),p.getString("name"),Store.day(p.getLong("created")));sheets.add(people);
  List<JSONObject>all=selected(snap,f,false),analytic=analytic(snap,f);Map<String,List<JSONObject>>days=new TreeMap<>(Collections.reverseOrder());for(JSONObject r:all)if(!r.getBoolean("deleted")){String k=r.getString("day")+"|"+r.getString("patientId");if(!days.containsKey(k))days.put(k,new ArrayList<>());days.get(k).add(r);}
  Xlsx.Sheet daily=new Xlsx.Sheet("每日评分汇总");daily.add("病人编号","姓名或称呼","记录日期","PSQI","NRS","AIS-8","HAMD-17","HAMA-14","PSQI状态","NRS状态","AIS状态","HAMD状态","HAMA状态","所取PSQI记录ID","所取NRS记录ID","所取AIS记录ID","所取HAMD记录ID","所取HAMA记录ID");
  for(List<JSONObject>records:days.values()){JSONObject first=records.get(0),p=patients.get(first.getString("patientId"));List<Object>line=new ArrayList<>(Arrays.asList(p.getString("code"),p.getString("name"),first.getString("day")));List<Object>status=new ArrayList<>(),ids=new ArrayList<>();for(String id:Scales.IDS){JSONObject best=null;int count=0;for(JSONObject r:records){if(!id.equals(Store.scaleOf(r.getJSONObject("data").toString())))continue;count++;if(r.getJSONObject("data").getBoolean("completed")&&(best==null||r.getLong("updated")>best.getLong("updated")||(r.getLong("updated")==best.getLong("updated")&&r.getString("id").compareTo(best.getString("id"))>0)))best=r;}line.add(best==null?null:best.getJSONObject("data").getInt("total"));status.add(count==0?"未记录":best==null?"草稿":count>1?"多份，取最新完成":"已完成");ids.add(best==null?null:best.getString("id"));}line.addAll(status);line.addAll(ids);daily.addList(line);}sheets.add(daily);
  Xlsx.Sheet records=new Xlsx.Sheet("逐次评分");records.add("记录ID","病人编号","姓名或称呼","记录日期","评估时间","量表","规则版本","回顾范围","状态","回收站","总分","是否纳入统计","评估人员","备注");Set<String>included=new HashSet<>();for(JSONObject r:analytic)included.add(r.getString("id"));Xlsx.Sheet detail=new Xlsx.Sheet("条目明细");detail.add("记录ID","病人编号","记录日期","量表","字段代码","条目名称","原始值","分值或选项含义");
  for(JSONObject r:all){JSONObject d=r.getJSONObject("data"),p=patients.get(r.getString("patientId"));String scale=Store.scaleOf(d.toString());Scales.Def definition=Scales.get(scale);Map<String,String>a=Store.answers(d.toString());boolean done=d.getBoolean("completed");records.add(r.getString("id"),p.getString("code"),p.getString("name"),r.getString("day"),a.get("assessmentTime"),definition.shortName,d.getString("rule"),definition.period,done?"已完成":"草稿",r.getBoolean("deleted")?"是":"否",done?d.getInt("total"):null,included.contains(r.getString("id"))?"是":"否",a.get("rater"),a.get("note"));for(String key:Scales.keys(scale)){String value=Form.get(a,key),meaning="";if(!scale.equals("PSQI")){for(Scales.Item item:definition.items)if(item.key.equals(key)&&value.matches("\\d{1,2}")){int n=Integer.parseInt(value);if(n<=item.max())meaning=item.options[n];}}detail.add(r.getString("id"),p.getString("code"),r.getString("day"),definition.shortName,key,Scales.label(scale,key),value,meaning);}if(done&&scale.equals("PSQI")){JSONArray scores=d.getJSONArray("scores");for(int n=0;n<7;n++)detail.add(r.getString("id"),p.getString("code"),r.getString("day"),"PSQI","factor"+(n+1),Form.FACTORS[n],scores.getInt(n),"0～3分因子");}}
  sheets.add(records);sheets.add(detail);Xlsx.Sheet stats=new Xlsx.Sheet("统计汇总");stats.add("量表","规则版本","有效记录数","病人数","均值","样本标准差","中位数","最小值","最大值");for(Stat stat:stats(snap,f))stats.add(Scales.get(stat.scale).shortName,stat.rule,stat.n,stat.patients,stat.mean,stat.sd,stat.median,stat.min,stat.max);sheets.add(stats);
  Xlsx.Sheet sources=new Xlsx.Sheet("量表来源");sources.add("量表","版本","计分范围","回顾范围","来源名称","原文链接","核对与实施说明","核对日期");for(String id:Scales.IDS){Scales.Def d=Scales.get(id);for(String[]source:Scales.sources(id))sources.add(d.shortName,d.rule,"0～"+d.max,d.period,source[0],source[1],source[2],"2026-11-14");}sheets.add(sources);return sheets;
 }
 public static String csv(JSONObject snap,Filter f)throws Exception{StringBuilder out=new StringBuilder("\uFEFF");Xlsx.Sheet sheet=workbook(snap,f).get(3);for(List<Object>row:sheet.rows){for(int c=0;c<row.size();c++){if(c>0)out.append(',');String text=row.get(c)==null?"":row.get(c).toString();if(text.matches("(?s)^\\s*[=+@-].*")||text.startsWith("\t")||text.startsWith("\r"))text="'"+text;out.append('"').append(text.replace("\"","\"\"")).append('"');}out.append("\r\n");}return out.toString();}
}
